import React, { useRef, useEffect, useState } from "react";
import styled from "styled-components";
import { motion, useReducedMotion } from "framer-motion";
import { animate, createScope, type Scope } from "animejs";

const Btn = styled(motion.button)<{ $variant: "primary" | "ghost" }>`
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  border: ${(p) =>
    p.$variant === "primary"
      ? "none"
      : `1px solid ${p.theme.colors.borderStrong}`};
  background: ${(p) =>
    p.$variant === "primary" ? p.theme.colors.gradient : "transparent"};
  color: ${(p) => (p.$variant === "primary" ? "#fff" : p.theme.colors.text)};
  padding: 0.9rem 1.6rem;
  border-radius: ${(p) => p.theme.radii.pill};
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  letter-spacing: -0.01em;
  box-shadow: ${(p) =>
    p.$variant === "primary" ? p.theme.shadows.button : "none"};
  transition: background ${(p) => p.theme.motion.durFast}
      ${(p) => p.theme.motion.easeOut},
    border-color ${(p) => p.theme.motion.durFast}
      ${(p) => p.theme.motion.easeOut},
    color ${(p) => p.theme.motion.durFast} ${(p) => p.theme.motion.easeOut};
  overflow: hidden;

  &:hover {
    ${(p) =>
      p.$variant === "ghost" &&
      `
      border-color: ${p.theme.colors.primary};
      color: ${p.theme.colors.primary};
    `}
  }

  &::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(
      circle 80px at var(--mouse-x, 50%) var(--mouse-y, 50%),
      rgba(255, 255, 255, 0.12),
      transparent 70%
    );
    opacity: 0;
    transition: opacity 0.3s ease;
    pointer-events: none;
  }

  &:hover::before {
    opacity: 1;
  }
`;

type Props = React.ComponentProps<typeof motion.button> & {
  children: React.ReactNode;
  variant?: "primary" | "ghost";
  /** 자석 강도. 0 = 없음. 기본 20. */
  strength?: number;
};

/**
 * 마우스가 가까이 오면 버튼이 살짝 끌려오는 magnetic 인터랙션.
 * anime.js v4로 더 부드러운 elastic spring 효과 적용.
 * `prefers-reduced-motion` 시 비활성화.
 */
const MagneticButton: React.FC<Props> = ({
  children,
  variant = "primary",
  strength = 20,
  ...rest
}) => {
  const ref = useRef<HTMLButtonElement>(null);
  const reduced = useReducedMotion();
  const [scope, setScope] = useState<Scope | null>(null);

  useEffect(() => {
    if (!ref.current || reduced) return;
    
    const s = createScope({ root: ref.current });
    setScope(s);

    return () => {
      s.revert();
    };
  }, [reduced]);

  const onMove = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (reduced || !ref.current || !scope) return;
    const r = ref.current.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    const cy = r.top + r.height / 2;
    const dx = (e.clientX - cx) / (r.width / 2);
    const dy = (e.clientY - cy) / (r.height / 2);
    
    // Radial gradient 위치 업데이트
    const relX = ((e.clientX - r.left) / r.width) * 100;
    const relY = ((e.clientY - r.top) / r.height) * 100;
    ref.current.style.setProperty("--mouse-x", `${relX}%`);
    ref.current.style.setProperty("--mouse-y", `${relY}%`);

    animate(ref.current, {
      x: dx * strength,
      y: dy * strength,
      duration: 420,
      ease: "outElastic(1.2, 0.6)",
    });
  };

  const onLeave = () => {
    if (reduced || !ref.current || !scope) return;
    animate(ref.current, {
      x: 0,
      y: 0,
      duration: 550,
      ease: "outElastic(1, 0.5)",
    });
  };

  const onTap = () => {
    if (reduced || !ref.current || !scope) return;
    animate(ref.current, {
      scale: [1, 0.94, 1],
      duration: 280,
      ease: "inOutQuad",
    });
  };

  return (
    <Btn
      ref={ref}
      $variant={variant}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
      onMouseDown={onTap}
      {...rest}
    >
      {children}
    </Btn>
  );
};

export default MagneticButton;
